/* ── механика i18n ── */
(function(){
const LS='synthotc';
let uid=null;
let LANG=localStorage.getItem(LS+'_lang_guest')||'en';
if(!I18N_LANGS.some(l=>l[0]===LANG)) LANG='en';
const REV={}; for(const L in D) for(const k in D[L]) if(REV[D[L][k]]==null) REV[D[L][k]]=k;
const dict=()=>D[LANG]||{};
window.t=function(s,p){ let d;
  if(LANG==='ru') d=s;
  else { d=dict()[s]; if(d==null) d=D.en[s]; if(d==null) d=s; }
  if(p) for(const k in p) d=d.split('{'+k+'}').join(p[k]); return d; };
function trans(s){ if(!s) return null;
  if(LANG==='ru'){ const k=REV[s]; return k!=null?k:null; }
  if(dict()[s]!=null) return dict()[s];
  const k=REV[s]; if(k!=null){ return dict()[k]!=null?dict()[k]:D.en[k]; }
  return null; }
window.applyLang=function(){
  if(!document.body) return;
  document.documentElement.lang=LANG;
  const w=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,null);
  const nodes=[]; while(w.nextNode()){ const n=w.currentNode, p=n.parentElement;
    if(p&&(p.tagName==='SCRIPT'||p.tagName==='STYLE')) continue; nodes.push(n); }
  for(const n of nodes){ const v=n.nodeValue; const tr=v&&v.trim()?trans(v.trim()):null;
    if(tr!=null&&tr!==v.trim()) n.nodeValue=v.replace(v.trim(),tr); }
  document.querySelectorAll('input[placeholder],textarea[placeholder]').forEach(el=>{
    const tr=trans(el.getAttribute('placeholder')); if(tr!=null) el.setAttribute('placeholder',tr); });
};
window.setLang=function(code){ if(!I18N_LANGS.some(l=>l[0]===code)) return;
  LANG=code; localStorage.setItem(uid? LS+'_lang_u'+uid : LS+'_lang_guest',code);
  applyLang(); renderLangUI(); if(window.onLangChanged) window.onLangChanged(); };
window.i18nBindUser=function(id){ uid=id; const v=localStorage.getItem(LS+'_lang_u'+id);
  if(v&&I18N_LANGS.some(l=>l[0]===v)) LANG=v; applyLang(); renderLangUI(); };
window.getLang=function(){ return LANG; };
window.carryLangToUser=function(id,force){ const k=LS+'_lang_u'+id; const g=localStorage.getItem(LS+'_lang_guest');
  if(g&&(force||!localStorage.getItem(k))) localStorage.setItem(k,g); };
window.renderLangUI=function(){
  const cur=(I18N_LANGS.find(l=>l[0]===LANG)||I18N_LANGS[0])[1];
  ['lang-cur-auth','lang-cur-user'].forEach(id=>{ const e=document.getElementById(id); if(e) e.textContent=cur; });
  const list=document.getElementById('lang-list');
  if(list) list.innerHTML=I18N_LANGS.map(l=>'<div class="um-item" style="'+(l[0]===LANG?'color:var(--accent);font-weight:700':'')+'" onclick="setLang(\''+l[0]+'\')">'+l[1]+'</div>').join('');
};
let moT=null;
const mo=new MutationObserver(()=>{ clearTimeout(moT); moT=setTimeout(()=>{ try{applyLang();}catch(e){} },150); });
function start(){ applyLang(); renderLangUI(); mo.observe(document.body,{childList:true,subtree:true,characterData:true}); }
if(document.body) start(); else document.addEventListener('DOMContentLoaded',start);
})();
